const scenes=[...document.querySelectorAll(".scene")],flash=document.getElementById("flash"),cv=document.getElementById("fx"),ctx=cv.getContext("2d");let current=0,pts=[];
function rs(){cv.width=innerWidth*devicePixelRatio;cv.height=innerHeight*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}addEventListener("resize",rs);rs();
function burst(n=120){for(let i=0;i<n;i++)pts.push({x:innerWidth/2,y:innerHeight/2,vx:(Math.random()-.5)*18,vy:(Math.random()-.7)*18,a:1,s:2+Math.random()*5})}
(function loop(){ctx.clearRect(0,0,innerWidth,innerHeight);pts=pts.filter(p=>p.a>.03);for(const p of pts){p.x+=p.vx;p.y+=p.vy;p.vy+=.25;p.a*=.97;ctx.globalAlpha=p.a;ctx.fillStyle=Math.random()>.5?"#e30613":Math.random()>.5?"#ffdc58":"#fff";ctx.fillRect(p.x,p.y,p.s,p.s*1.7)}ctx.globalAlpha=1;requestAnimationFrame(loop)})();
let transitioning=false;
const transitionModes=["wipe-x","wipe-y","split","diagonal","zoom-cut"];
let transitionCount=0;
function go(i){
  if(i<0||i>=scenes.length||transitioning||i===current)return;
  transitioning=true;
  const old=scenes[current],next=scenes[i],curtain=document.getElementById("pageTransition");
  const mode=transitionModes[transitionCount++%transitionModes.length];

  curtain.className="page-transition "+mode;
  old.classList.add("scene-leaving","leave-"+mode);

  // Some transitions move horizontally, some vertically, some use a zoom cut.
  requestAnimationFrame(()=>curtain.classList.add("closing"));

  setTimeout(()=>{
    scenes.forEach(s=>{
      s.classList.remove("active","scene-leaving","scene-entering",
        "leave-wipe-x","leave-wipe-y","leave-split","leave-diagonal","leave-zoom-cut");
    });
    next.classList.add("active","scene-entering","enter-"+mode);
    current=i;
    if(i===5){
      next.scrollTop=0;
      document.querySelectorAll(".memory-rail .pc").forEach(c=>c.classList.remove("revealed"));
    }
    curtain.classList.remove("closing");
    curtain.classList.add("opening");
    setTimeout(()=>next.classList.remove("scene-entering","enter-"+mode),120);
  }, mode==="zoom-cut"?560:680);

  setTimeout(()=>{
    curtain.className="page-transition";
    transitioning=false;
  }, mode==="zoom-cut"?1180:1420);
}
document.querySelectorAll(".next").forEach(b=>b.onclick=()=>go(current+1));
function holdAction(btn,duration,done){let raf,start=0,active=false,bar=btn.querySelector("i");const tick=t=>{if(!active)return;if(!start)start=t;let p=Math.min(1,(t-start)/duration);bar.style.width=p*100+"%";if(p>=1){active=false;done()}else raf=requestAnimationFrame(tick)};btn.onpointerdown=e=>{e.preventDefault();active=true;start=0;try{btn.setPointerCapture(e.pointerId)}catch{};raf=requestAnimationFrame(tick)};btn.onpointerup=btn.onpointercancel=()=>{if(active){active=false;cancelAnimationFrame(raf);bar.style.width="0%"}}}
holdAction(document.getElementById("unlock"),1300,()=>{burst(100);go(1);setTimeout(countdown,350)});


let beepCtx = null;

function playCountdownBeep(finalBeep = false){
  if(!beepCtx){
    beepCtx = new (window.AudioContext || window.webkitAudioContext)();
  }

  const osc = beepCtx.createOscillator();
  const gain = beepCtx.createGain();

  osc.connect(gain);
  gain.connect(beepCtx.destination);

  // 3 2 1 = เสียงต่ำ / ACCESS = เสียงสูงและยาว
  osc.frequency.value = finalBeep ? 1050 : 720;
  osc.type = "sine";

  const now = beepCtx.currentTime;
  const duration = finalBeep ? 0.65 : 0.16;

  gain.gain.setValueAtTime(0, now);
  gain.gain.linearRampToValueAtTime(0.18, now + 0.015);
  gain.gain.setValueAtTime(0.18, now + duration - 0.05);
  gain.gain.exponentialRampToValueAtTime(0.001, now + duration);

  osc.start(now);
  osc.stop(now + duration);
}


function countdown(){
  const values=["3","2","1"];
  const el=document.getElementById("count");
  let i=0;

  el.textContent="";

  function showNext(){

    // 3 2 1 จบแล้ว
    if(i >= values.length){

      // ขึ้น ACCESS ก่อน
      el.textContent="ACCESS";

// ตื๊ดดดด — เสียงสูงและยาวกว่า
playCountdownBeep(true);

      el.getAnimations().forEach(a=>a.cancel());

      el.animate([
        {
          opacity:0,
          transform:"scale(.8)",
          filter:"blur(15px)"
        },
        {
          offset:.35,
          opacity:1,
          transform:"scale(1.05)",
          filter:"blur(0)"
        },
        {
          opacity:1,
          transform:"scale(1)",
          filter:"blur(0)"
        }
      ],{
        duration:900,
        easing:"cubic-bezier(.16,.84,.2,1)",
        fill:"both"
      });

      // เพลงเริ่มตรงจังหวะเฉลยหลัง 3 2 1
      startMusic();

      // แล้วค่อย transition เข้าหน้าแมนยู
      setTimeout(()=>{
        go(2);
      },950);

      return;
    }

    el.textContent=values[i++];

    playCountdownBeep(false);

    el.getAnimations().forEach(a=>a.cancel());

    el.animate([
      {
        opacity:0,
        transform:"translate3d(0,60px,0) scale(.72)",
        filter:"blur(18px)"
      },
      {
        offset:.22,
        opacity:1,
        transform:"translate3d(0,0,0) scale(1.035)",
        filter:"blur(0)"
      },
      {
        offset:.68,
        opacity:1,
        transform:"translate3d(0,0,0) scale(1)",
        filter:"blur(0)"
      },
      {
        opacity:0,
        transform:"translate3d(0,-46px,0) scale(.9)",
        filter:"blur(13px)"
      }
    ],{
      duration:1450,
      easing:"cubic-bezier(.16,.84,.2,1)",
      fill:"both"
    });

    setTimeout(showNext,1520);
  }

  showNext();
}

const blow=document.getElementById("blow"),bp=document.getElementById("blowpct");let ba=false,bs=0,br;
blow.onpointerdown=e=>{e.preventDefault();ba=true;bs=performance.now();try{blow.setPointerCapture(e.pointerId)}catch{};const tick=()=>{if(!ba)return;let p=Math.min(100,(performance.now()-bs)/14);blow.querySelector("i").style.width=p+"%";bp.textContent=Math.round(p)+"%";if(p>=100){ba=false;document.querySelector(".candles").classList.add("out");bp.textContent="WISH LOCKED ✓";burst(70);setTimeout(()=>go(8),900)}else br=requestAnimationFrame(tick)};tick()};
blow.onpointerup=blow.onpointercancel=()=>{if(ba){ba=false;cancelAnimationFrame(br);blow.querySelector("i").style.width="0";bp.textContent="0%"}};
const charge=document.getElementById("charge"),powerEl=document.getElementById("power"),ball=document.getElementById("ball");let ca=false,pow=0,dir=1,last=0,cr;
charge.onpointerdown=e=>{e.preventDefault();ca=true;last=0;try{charge.setPointerCapture(e.pointerId)}catch{};const tick=t=>{if(!ca)return;if(!last)last=t;pow+=(t-last)*.08*dir;if(pow>=100){pow=100;dir=-1}if(pow<=8){pow=8;dir=1}last=t;charge.querySelector("i").style.width=pow+"%";powerEl.textContent=Math.round(pow)+"%";cr=requestAnimationFrame(tick)};cr=requestAnimationFrame(tick)};
function shoot(){if(!ca)return;ca=false;cancelAnimationFrame(cr);let p=Math.round(pow);powerEl.textContent=p>=90?"PERFECT!":p>=50?"GOOD SHOT!":"GOAL!";ball.classList.add("shot");burst(p>=90?220:130);setTimeout(()=>{ball.classList.remove("shot");go(9);burst(280)},900)}
charge.onpointerup=charge.onpointercancel=shoot;
document.getElementById("replay").onclick=()=>{document.querySelector(".candles").classList.remove("out");blow.querySelector("i").style.width="0";bp.textContent="0%";pow=0;charge.querySelector("i").style.width="0";powerEl.textContent="0%";go(0)};
