  const c=document.createElement("canvas");c.width=1080;c.height=1920;const x=c.getContext("2d");

  const g=x.createLinearGradient(0,0,1080,1920);g.addColorStop(0,"#070707");g.addColorStop(.58,"#260003");g.addColorStop(1,"#75000b");x.fillStyle=g;x.fillRect(0,0,1080,1920);
  x.globalAlpha=.12;x.drawImage(crest,560,1050,650,650);x.globalAlpha=1;
