  const shade=x.createLinearGradient(0,900,0,1170);shade.addColorStop(0,"rgba(0,0,0,0)");shade.addColorStop(1,"rgba(0,0,0,.6)");x.fillStyle=shade;x.fillRect(bx,850,bw,320);

